-- 204: Original BrillaPrep WASSCE BrillaPrep transitional Leatherwork beta content blueprint questions, part 2.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_204_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_204_guard;
INSERT INTO _migration_204_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_leatherwork_b004_005' AND NOT (q.topic_id IS 'topic_was_leatherwork_b004_1' AND q.subject_id IS 'subj_wassce_leatherwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why should leather thickness and stretch be checked in several zones before laying out a bag pattern?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. A single centre reading is sufficient to represent the mechanical behaviour of the hide","B. Natural variation determines which zones suit straps, gussets and broad panels","C. Stretch direction matters for garment leather but not for loaded straps or handles","D. Matching surface colour indicates equal substance and firmness across the zones"]' AND q.correct_answer IS 'B' AND q.explanation IS 'A hide varies from firm backbone areas to stretchier belly and flank zones, so measuring and flexing several areas helps assign each component to material that suits its load and form. Therefore the correct answer is B: Natural variation determines which zones suit straps, gussets and broad panels.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_leatherwork_b004_1' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_leatherwork_b004_005' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Leatherwork practice aligned to WAEC Ghana examiner evidence and Ghana curriculum sources; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_204_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_leatherwork_b004_006' AND NOT (q.topic_id IS 'topic_was_leatherwork_b004_2' AND q.subject_id IS 'subj_wassce_leatherwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which description correctly identifies combination tanning?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Fresh hides are wet salted and later brined, with the two preservation steps counted as separate tannages","B. Finished leather is bleached and then dyed, combining two colour treatments into a tannage","C. A pickled pelt receives one chrome-tanning bath followed by neutralisation and drying","D. The leather receives two compatible tannages in sequence so their properties complement one another"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Combination tanning deliberately applies two compatible tanning systems, such as vegetable tannage followed by chrome or another mineral tannage, to combine useful handle, colour, strength or ageing properties. Therefore the correct answer is D: The leather receives two compatible tannages in sequence so their properties complement one another.' AND q.difficulty IS 'hard' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_leatherwork_b004_2' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_leatherwork_b004_006' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Leatherwork practice aligned to WAEC Ghana examiner evidence and Ghana curriculum sources; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_204_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_leatherwork_b004_007' AND NOT (q.topic_id IS 'topic_was_leatherwork_b004_2' AND q.subject_id IS 'subj_wassce_leatherwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the main purpose of fleshing before tanning?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Introduce lubricating oils between fibres before drying","B. Abrade the grain lightly so pigment can cover natural marks","C. Remove adhering fat, connective tissue and flesh from the inner surface","D. Reduce the pH with acid and salt before mineral tanning"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Fleshing clears residual tissue that would decay or obstruct even chemical penetration, leaving a cleaner pelt for subsequent beamhouse and tanning operations. Therefore the correct answer is C: Remove adhering fat, connective tissue and flesh from the inner surface.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_leatherwork_b004_2' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_leatherwork_b004_007' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Leatherwork practice aligned to WAEC Ghana examiner evidence and Ghana curriculum sources; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_204_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_leatherwork_b004_008' AND NOT (q.topic_id IS 'topic_was_leatherwork_b004_2' AND q.subject_id IS 'subj_wassce_leatherwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What useful effect does controlled liming have during beamhouse processing?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. It deposits the final resin topcoat over the grain surface","B. It neutralises finished leather after dyeing and fatliquoring","C. It lowers pH to prepare the pelt directly for chrome tanning","D. It loosens hair and opens the fibre structure for further cleaning"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Alkaline liming swells and opens collagen while helping remove hair and unwanted proteins; concentration and time must be controlled to avoid weakening the pelt. Therefore the correct answer is D: It loosens hair and opens the fibre structure for further cleaning.' AND q.difficulty IS 'medium' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_leatherwork_b004_2' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_leatherwork_b004_008' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Leatherwork practice aligned to WAEC Ghana examiner evidence and Ghana curriculum sources; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_leatherwork_b004_005', 'topic_was_leatherwork_b004_1', 'subj_wassce_leatherwork', 'exam_wassce', NULL, NULL, 'Why should leather thickness and stretch be checked in several zones before laying out a bag pattern?', 'multiple_choice', NULL, '["A. A single centre reading is sufficient to represent the mechanical behaviour of the hide","B. Natural variation determines which zones suit straps, gussets and broad panels","C. Stretch direction matters for garment leather but not for loaded straps or handles","D. Matching surface colour indicates equal substance and firmness across the zones"]', 'B', 'A hide varies from firm backbone areas to stretchier belly and flank zones, so measuring and flexing several areas helps assign each component to material that suits its load and form. Therefore the correct answer is B: Natural variation determines which zones suit straps, gussets and broad panels.', 'medium', '3', '3', '90', NULL, NULL, '1', NULL, 'st_was_leatherwork_b004_1', 'Explain', 'AO2', NULL, NULL, 'board_waec');
