INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_leatherwork_b004_007', 'topic_was_leatherwork_b004_2', 'subj_wassce_leatherwork', 'exam_wassce', NULL, NULL, 'What is the main purpose of fleshing before tanning?', 'multiple_choice', NULL, '["A. Introduce lubricating oils between fibres before drying","B. Abrade the grain lightly so pigment can cover natural marks","C. Remove adhering fat, connective tissue and flesh from the inner surface","D. Reduce the pH with acid and salt before mineral tanning"]', 'C', 'Fleshing clears residual tissue that would decay or obstruct even chemical penetration, leaving a cleaner pelt for subsequent beamhouse and tanning operations. Therefore the correct answer is C: Remove adhering fat, connective tissue and flesh from the inner surface.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, 'st_was_leatherwork_b004_2', 'Identify', 'AO1', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_leatherwork_b004_008', 'topic_was_leatherwork_b004_2', 'subj_wassce_leatherwork', 'exam_wassce', NULL, NULL, 'What useful effect does controlled liming have during beamhouse processing?', 'multiple_choice', NULL, '["A. It deposits the final resin topcoat over the grain surface","B. It neutralises finished leather after dyeing and fatliquoring","C. It lowers pH to prepare the pelt directly for chrome tanning","D. It loosens hair and opens the fibre structure for further cleaning"]', 'D', 'Alkaline liming swells and opens collagen while helping remove hair and unwanted proteins; concentration and time must be controlled to avoid weakening the pelt. Therefore the correct answer is D: It loosens hair and opens the fibre structure for further cleaning.', 'medium', '2', '2', '90', NULL, NULL, '1', NULL, 'st_was_leatherwork_b004_2', 'Identify', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'wassce-visual-arts-beta-004', 'automated_beta', 'beta', 'Original BrillaPrep transitional Leatherwork practice aligned to WAEC Ghana examiner evidence and Ghana curriculum sources; not official WAEC examination material or a copied past paper.', 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf', 0, 1 FROM questions WHERE id IN ('q_was_leatherwork_b004_005', 'q_was_leatherwork_b004_006', 'q_was_leatherwork_b004_007', 'q_was_leatherwork_b004_008');
